  for(const [key,pane]of Object.entries(groups)){if(!pane.children.length)pane.append(make('p',key==='tokens'?'Tokens indisponíveis para este acesso ou situação.':key==='cancelamento'?'Cancelamento indisponível para este acesso ou situação.':'Nenhuma ação disponível nesta seção.'));detail.append(pane);}
