 const tableSizeObserver=new ResizeObserver(entries=>{
  for(const {target:t} of entries){
   const rows=t.tBodies[0]?.rows;if(!rows?.length||!t.getBoundingClientRect().height)continue;
   if(rows.length<=15){t.parentElement.style.maxHeight='';continue;}
   const last=rows[Math.min(15,rows.length)-1];
   const wrap=t.parentElement,chrome=wrap.offsetHeight-wrap.clientHeight;
   wrap.style.maxHeight=Math.floor(last.getBoundingClientRect().bottom-t.getBoundingClientRect().top)+chrome+'px';
  }
 });
 const secret=make('p');secret.id='pc05Secret';secret.role='status';secret.style.overflowWrap='anywhere';
 function clearSecrets(){visibleToken=null;secret.replaceChildren();}
 function reveal(result,tipo){
  const token={codigo:String(result.codigo),texto:(tipo==='ENTRADA'?'Token de entrada: ':'Token de saída: ')+String(result.codigo)};visibleToken=token;
  const description=make('span',(tipo==='ENTRADA'?'Entrada':'Saída')+' · válido até '+new Date(result.expiraEmUtc).toLocaleTimeString('pt-BR'));
  const code=make('input');code.type='text';code.readOnly=true;code.value=token.codigo;code.setAttribute('aria-label','Token gerado');code.autocomplete='off';code.spellcheck=false;
  const feedback=make('span');feedback.role='status';feedback.setAttribute('aria-live','polite');
  const copy=button('Copiar token',async()=>{
   if(visibleToken!==token)return;
   try{if(!navigator.clipboard?.writeText)throw Error('Copia indisponivel');await navigator.clipboard.writeText(token.texto);if(visibleToken===token&&code.isConnected){code.value=token.codigo;code.classList.remove('pc05-copy-text');feedback.textContent='Token copiado!';}}
   catch{if(visibleToken!==token||!code.isConnected)return;code.value=token.texto;code.classList.add('pc05-copy-text');code.focus();code.select();code.setSelectionRange(0,code.value.length);feedback.textContent='Texto selecionado. Use a opção Copiar do seu dispositivo.';}
  });
  secret.className='pc05-token';secret.replaceChildren(description,code,copy,feedback);
 }

