 async function exportContracts(format,menu){
  if(busy||!catalog||document.hidden||host?.hidden)return;
  clearTimeout(filterTimer);
  const draft=draftFilters();if([...new Set([...Object.keys(draft),...Object.keys(filters)])].some(key=>(draft[key]||'')!==(filters[key]||''))){message.textContent='Aplique os filtros alterados antes de exportar.';return;}
  const revision=epoch,currentAccount=account,label=format==='pdf'?'PDF':'Excel',mime=format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
  const active=()=>revision===epoch&&account===currentAccount&&!document.hidden&&!host?.hidden;
  const query=new URLSearchParams(filters);menu.open=false;lock(true);message.textContent='Preparando arquivo '+label+'...';
  try{
   const response=await(window.jettaProtectedFetch||fetch)('/api/pc04/contratacoes/exportar.'+format+(query.size?'?'+query:''),{credentials:'same-origin',cache:'no-store'});
   if(!active())return;
   if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.erro==='EXPORTACAO_PDF_OCUPADA'?'Já existe uma exportação PDF em andamento. Tente novamente em instantes.':errors[data.erro]||'Não foi possível exportar. Tente novamente em instantes.');}
   if(response.headers.get('content-type')?.split(';')[0].trim().toLowerCase()!==mime)throw Error('O servidor não retornou um arquivo '+label+' válido.');
   const blob=await response.blob();if(!active())return;
   const disposition=response.headers.get('content-disposition')||'',encoded=/filename\*=UTF-8''([^;]+)/i.exec(disposition),plain=/filename="([^"]+)"|filename=([^;]+)/i.exec(disposition);
   let name=plain?.[1]||plain?.[2]||'contratacoes.'+format;if(encoded){try{name=decodeURIComponent(encoded[1]);}catch{}}
   name=name.trim().replace(/[\\/\x00-\x1f]/g,'_');if(!name.toLowerCase().endsWith('.'+format))name='contratacoes.'+format;
   const url=URL.createObjectURL(blob),link=make('a');link.href=url;link.download=name;link.hidden=true;document.body.append(link);try{link.click();}finally{link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
   message.textContent='Arquivo '+label+' exportado.';
  }catch(err){if(active())message.textContent=err.message;}
  finally{if(revision===epoch&&account===currentAccount)lock(false);}
 }
